const PAGES={
 cataract:{title:'백내장',group:1,en:'CATARACT',headline:'뿌옇게 흐려진 시야,<br>원인을 찾는 것부터.',lead:'시야의 변화를 살피고, 생활에 맞는 치료 방향을 상담합니다.',image:'image7.png',definition:'백내장은 눈 속의 투명한 수정체가 혼탁해져 시야가 뿌옇게 보이는 질환입니다. 불편한 정도와 눈 상태를 확인해 경과 관찰이나 수술을 상담합니다.',symptoms:['시야가 흐리고 뿌옇게 보입니다.','밝은 빛이나 조명에서 눈부심이 심합니다.','한쪽 눈으로 보아도 물체가 겹쳐 보입니다.','밤에 물체를 구분하기 어려워집니다.'],exams:[['세극등검사','수정체의 혼탁과 눈 앞쪽의 상태를 살핍니다.'],['안저검사','망막과 시신경 상태를 함께 확인합니다.'],['수술 전 검사','필요에 따라 각막내피세포검사와 인공수정체 도수 측정 등을 시행합니다.']],treatments:[['경과 관찰','시력과 일상생활의 불편 정도를 확인하며 검사 간격을 정합니다.'],['백내장 수술 상담','혼탁한 수정체를 제거하고 인공수정체를 삽입하는 방법을 상담합니다. 수술 시기와 렌즈 선택은 검사 후 결정합니다.']],faq:[['백내장이 있으면 바로 수술해야 하나요?','혼탁 정도와 생활의 불편, 다른 눈 질환 등을 함께 고려합니다. 검사 후 의료진과 시기를 상의하세요.'],['인공수정체는 어떻게 선택하나요?','눈 상태와 독서·컴퓨터·운전 등 자주 사용하는 생활 거리를 고려합니다. 각 렌즈의 특성과 주의사항을 상담합니다.']],source:'cataracts'},
 presbyopia:{title:'노안',group:1,en:'PRESBYOPIA',headline:'가까운 글씨가 멀어질 때,<br>눈의 변화를 살펴봅니다.',lead:'노안과 다른 눈 질환을 구분하고, 생활 거리에 맞는 교정 방법을 상담합니다.',image:'image4.png',definition:'노안은 나이가 들며 수정체의 조절 능력이 줄어 가까운 물체에 초점을 맞추기 어려워지는 변화입니다. 백내장 등 다른 원인이 함께 있는지 검사로 확인합니다.',symptoms:['가까운 글씨를 멀리 두고 읽습니다.','작은 글씨가 흐려 보입니다.','가까운 곳을 오래 보면 눈이 피로합니다.','근거리 작업에 더 밝은 조명이 필요합니다.'],exams:[['시력·굴절검사','원거리와 근거리 시력, 굴절 상태를 확인합니다.'],['눈 건강 검사','증상에 따라 수정체와 망막 등 다른 눈 질환을 살핍니다.']],treatments:[['안경 교정','돋보기 또는 다초점 안경 등 필요한 거리와 사용 목적에 맞는 교정을 상담합니다.'],['수술적 교정 상담','눈의 상태와 동반 질환에 따라 적합성, 기대할 수 있는 점과 주의사항을 설명합니다.']],faq:[['노안과 백내장은 같은 건가요?','노안은 조절 능력의 변화이고, 백내장은 수정체가 혼탁해지는 질환입니다. 두 가지가 함께 나타날 수 있어 검사가 필요합니다.']],source:'presbyopia'},
 lens:{title:'인공수정체',group:1,en:'INTRAOCULAR LENS',headline:'눈의 상태와 생활 거리,<br>함께 생각하는 렌즈 선택.',lead:'백내장 수술에 사용하는 인공수정체의 특성을 알아보세요.',image:'image7.png',definition:'인공수정체는 백내장 수술에서 혼탁한 수정체를 대신하는 렌즈입니다. 렌즈 종류마다 초점을 맞추는 거리와 특성이 다릅니다.',symptoms:['책이나 휴대폰을 자주 사용합니다.','컴퓨터 작업이 많습니다.','야간 운전이 잦습니다.','안경 사용에 대한 선호가 있습니다.'],symptomTitle:'상담 전 생각해 보세요',exams:[['눈 상태 확인','시력·굴절, 각막, 망막 등 검사 결과를 바탕으로 렌즈 적합성을 확인합니다.'],['생활 방식 상담','자주 보는 거리와 직업, 취미, 안경 사용 선호를 함께 이야기합니다.']],treatments:[['단초점 인공수정체','한 초점 거리를 중심으로 선택합니다. 다른 거리를 볼 때 안경이 필요할 수 있습니다.'],['다초점 등 인공수정체','여러 거리의 시생활을 고려해 상담합니다. 눈부심이나 빛 번짐 등 특성과 주의사항을 확인해야 합니다.']],faq:[['특정 렌즈가 누구에게나 좋은가요?','다른 눈 질환과 생활 방식에 따라 적합한 선택이 다릅니다. 수술 전 검사 결과를 바탕으로 상담합니다.']],source:'cataracts'},
 'retina-amd':{title:'황반변성',group:2,en:'MACULAR DEGENERATION',headline:'시야의 중심에 생긴 변화,<br>세심하게 살펴봅니다.',lead:'글씨와 얼굴을 보는 중심 시력의 변화를 확인합니다.',image:'image8.png',definition:'황반변성은 망막의 중심인 황반에 변화가 생겨 중심 시력이 영향을 받는 질환입니다. 유형과 진행 정도에 따라 관찰과 치료 방향이 달라집니다.',symptoms:['직선이 휘어져 보입니다.','시야의 중심이 흐리게 보입니다.','글씨를 읽거나 얼굴을 구분하기 어렵습니다.','초기에는 변화를 느끼지 못할 수 있습니다.'],exams:[['안저검사','황반과 망막 상태를 확인합니다.'],['빛간섭단층촬영(OCT)','황반의 단면과 구조 변화를 살핍니다.']],treatments:[['정기 관찰','유형과 진행 정도에 따라 경과를 확인합니다.'],['치료 상담','검사 결과에 따라 주사 치료 등 필요한 치료 선택지를 상담합니다.']],faq:[['직선이 갑자기 휘어 보이면 어떻게 하나요?','새로운 시야 변화가 생기면 빠른 안과 진료가 필요합니다. 증상만으로 원인을 구분하기는 어렵습니다.']],source:'age-related-macular-degeneration'},
 'retina-diabetes':{title:'당뇨망막병증',group:2,en:'DIABETIC RETINOPATHY',headline:'당뇨가 있다면,<br>눈 건강도 함께 살펴야 합니다.',lead:'증상이 없어도 망막의 상태를 확인하는 것이 중요합니다.',image:'image8.png',definition:'당뇨망막병증은 당뇨로 인해 망막의 작은 혈관에 변화가 생기는 질환입니다. 초기에는 증상이 없을 수 있어 정기적인 눈 검사가 필요합니다.',symptoms:['초기에는 특별한 증상이 없을 수 있습니다.','시야가 흐리거나 시력이 변합니다.','검은 점이나 떠다니는 물체가 보입니다.','시력 저하가 갑자기 나타날 수 있습니다.'],exams:[['안저검사','망막의 혈관과 출혈 등 변화를 확인합니다.'],['추가 정밀검사','눈 상태에 따라 황반부와 혈관 상태를 더 살펴봅니다.']],treatments:[['전신 건강과 함께 관리','혈당과 혈압 등 전신 상태 관리, 정기적인 안과 검사를 함께 진행합니다.'],['진행 정도에 따른 치료','관찰, 주사, 레이저 또는 수술 등 필요한 치료 방향을 상담합니다.']],faq:[['잘 보이면 검사를 받지 않아도 되나요?','초기에는 증상이 없을 수 있습니다. 검사 간격은 당뇨의 상태와 눈 검사 결과를 바탕으로 정합니다.']],source:'diabetic-retinopathy'},
 'retina-detachment':{title:'망막박리',group:2,en:'RETINAL DETACHMENT',headline:'갑작스러운 시야 변화,<br>진료를 미루지 마세요.',lead:'번쩍이는 빛, 늘어난 비문증, 커튼 같은 그림자가 보인다면 빠른 확인이 필요합니다.',image:'image8.png',definition:'망막박리는 눈 안쪽의 망막이 원래 위치에서 분리되는 질환입니다. 시력을 보호하기 위해 빠른 검사와 치료 판단이 필요합니다.',symptoms:['떠다니는 점이 갑자기 많이 늘어납니다.','번쩍이는 빛이 보입니다.','시야에 커튼 같은 그림자가 드리웁니다.','시야 일부가 가려지거나 시력이 떨어집니다.'],exams:[['산동 안저검사','망막의 열공과 박리 여부를 확인합니다.'],['추가 영상검사','필요한 경우 OCT나 초음파 등으로 망막 상태를 살핍니다.']],treatments:[['빠른 진료','위 증상이 갑자기 생기면 가까운 안과 또는 응급실을 즉시 방문하세요.'],['상태에 따른 치료','망막의 상태와 분리 범위에 따라 레이저 또는 수술 등 치료를 결정합니다.']],notice:'갑자기 비문증이 늘거나 번쩍이는 빛, 커튼 같은 시야 가림이 생기면 즉시 안과 또는 응급실에서 확인하세요.',source:'retinal-detachment'},
 'retina-glaucoma':{title:'녹내장',group:2,en:'GLAUCOMA',headline:'느끼지 못한 변화까지,<br>시신경을 살펴봅니다.',lead:'안압과 시신경, 시야의 변화를 함께 확인합니다.',image:'image8.png',definition:'녹내장은 시신경이 손상되어 시야에 영향을 주는 질환입니다. 초기에는 스스로 증상을 느끼기 어려울 수 있어 검사와 경과 관찰이 중요합니다.',symptoms:['초기에는 증상이 없을 수 있습니다.','주변 시야가 점차 좁아질 수 있습니다.','안압 수치만으로 판단하기 어렵습니다.','가족력 등 위험요인이 있다면 검사를 상담합니다.'],exams:[['안압·안저검사','안압과 시신경 상태를 살핍니다.'],['시야 및 시신경 검사','시야의 변화와 시신경의 구조를 함께 확인합니다.']],treatments:[['지속적인 경과 관리','검사 결과를 비교하며 상태와 진행 여부를 확인합니다.'],['안압을 조절하는 치료','눈 상태에 따라 약물, 레이저 또는 수술 등의 치료를 상담합니다.']],faq:[['안압이 정상이면 녹내장이 아닌가요?','안압이 정상 범위여도 시신경 손상이 있을 수 있습니다. 시신경과 시야 검사 등을 종합해 판단합니다.']],source:'glaucoma'},
 'pediatric-strabismus':{title:'사시·약시',group:3,en:'PEDIATRIC EYE CARE',headline:'아이의 눈은,<br>더 이른 관심이 필요합니다.',lead:'눈의 정렬과 시력 발달을 함께 살펴봅니다.',image:'image9.png',definition:'사시는 두 눈의 정렬이 일치하지 않는 상태입니다. 약시는 시력 발달 과정에서 한쪽 또는 양쪽 눈의 시력이 충분히 발달하지 않은 상태를 말합니다. 원인과 정도를 확인해 치료 방향을 결정합니다.',symptoms:['두 눈이 서로 다른 방향을 봅니다.','한쪽 눈을 감거나 고개를 기울입니다.','물체를 가까이에서 보려고 합니다.','아이 스스로 불편을 말하지 못할 수 있습니다.'],exams:[['시력·굴절검사','아이의 연령에 맞춰 시력과 굴절 상태를 살핍니다.'],['사시·입체시검사','눈의 정렬과 두 눈을 함께 쓰는 기능을 확인합니다.']],treatments:[['안경·약시 치료 상담','굴절 상태를 교정하고, 필요에 따라 가림 치료 등 시력 발달을 돕는 방법을 상담합니다.'],['사시 치료 상담','사시의 종류와 정도에 따라 안경, 약물 또는 수술적 치료를 결정합니다.']],faq:[['아이가 잘 보인다고 해도 검사가 필요한가요?','한쪽 눈이 잘 보이면 반대쪽의 시력 저하를 모르고 지낼 수 있습니다. 아이의 눈 상태를 확인하는 검사를 상담하세요.']],source:'amblyopia-lazy-eye'},
 'pediatric-dream':{title:'드림렌즈',group:3,en:'DREAM LENS',headline:'아이의 시생활을 생각하는<br>드림렌즈 상담.',lead:'눈 상태와 착용 관리 가능성을 확인하고 적합성을 상담합니다.',image:'image10.png',definition:'드림렌즈는 잠자는 동안 착용하는 특수 콘택트렌즈로, 낮 동안 안경 없이 생활하도록 돕는 방법입니다. 눈의 상태와 검사 결과, 위생 관리 가능성을 고려해 적합성을 판단합니다.',symptoms:['아이의 근시 상태를 확인하고 싶습니다.','낮 동안 안경 사용의 불편이 있습니다.','보호자가 렌즈 관리를 도울 수 있습니다.','정기적인 경과 확인이 가능합니다.'],symptomTitle:'상담에서 함께 확인합니다',exams:[['시력·굴절검사','현재 시력과 굴절 상태를 확인합니다.'],['각막 및 착용 상태 확인','눈 상태와 렌즈의 적합성을 확인하고 관리 방법을 안내합니다.']],treatments:[['검사 후 착용 상담','착용 적합성을 확인한 뒤 렌즈 사용 방법을 안내합니다.'],['위생 관리와 정기검진','렌즈 세척과 관리법을 지키고, 불편이나 충혈 등이 생기면 착용을 중단하고 진료를 받습니다.']],faq:[['모든 아이가 착용할 수 있나요?','눈의 상태와 관리 여건에 따라 적합성이 달라집니다. 검사 후 의료진과 상담해야 합니다.'],['효과는 계속 유지되나요?','개인별 차이가 있으며 지속적인 착용과 관리가 필요합니다. 기대할 수 있는 점과 주의사항을 상담합니다.']]},
 'pediatric-exam':{title:'소아 안종합검진',group:3,en:'CHILDREN’S EYE EXAMINATION',headline:'아이의 눈이 자라는 시간,<br>함께 살펴봅니다.',lead:'시력뿐 아니라 눈의 정렬과 기능, 건강 상태를 확인합니다.',image:'image9.png',definition:'아이의 연령과 협조도, 증상에 맞춰 검사 항목을 선택합니다. 시력 발달과 굴절 상태, 사시 여부 및 눈 건강을 함께 살펴봅니다.',tests:['시력검사','사시검사','정밀검사','입체시검사','색각검사','안압검사','망막·시신경검사','외안부검사','굴절이상검사','현미경검사','안근육기능검사'],exams:[['검사 전 상담','아이의 증상과 가족력, 이전 검사 및 안경 사용 여부를 이야기합니다.'],['연령에 맞춘 검사','필요한 검사를 선택해 시력과 눈 기능, 건강 상태를 확인합니다.']],treatments:[['결과 설명','아이의 눈 상태와 필요한 교정 또는 치료 방향을 설명합니다.'],['경과 확인','시력 발달과 치료 경과에 따라 검사 간격을 안내합니다.']]},
 'care-dry':{title:'안구건조증',group:4,en:'DRY EYE',headline:'눈의 불편함,<br>원인부터 살펴봅니다.',lead:'눈물과 눈 표면의 상태를 확인하고 관리 방법을 상담합니다.',image:'image11.png',definition:'안구건조증은 눈물이 충분하지 않거나 눈물막이 불안정해 눈 표면에 불편함이 생기는 상태입니다. 증상과 눈 표면 상태를 함께 확인합니다.',symptoms:['눈이 뻑뻑하거나 이물감이 있습니다.','눈이 따갑거나 화끈거립니다.','시야가 흐려졌다가 좋아집니다.','눈이 충혈되거나 쉽게 피로합니다.'],exams:[['증상과 생활 환경 상담','화면 사용, 렌즈 착용, 복용약 및 환경을 확인합니다.'],['눈 표면 검사','눈물과 각막, 눈꺼풀 등 눈 표면의 상태를 살핍니다.']],treatments:[['생활과 눈 표면 관리','화면 사용 중 휴식, 환경 조절 및 눈꺼풀 관리 등을 상담합니다.'],['상태에 맞는 치료','눈의 상태와 원인에 따라 인공눈물 등 필요한 치료를 선택합니다.']],faq:[['인공눈물만 사용하면 되나요?','원인과 증상에 따라 관리 방법이 달라집니다. 불편이 지속되면 눈 표면 상태를 검사하고 상담하세요.']],source:'dry-eye'},
 'care-oculoplastic':{title:'안성형',group:4,en:'OCULOPLASTIC CARE',headline:'눈 주변의 불편함까지,<br>기능을 생각하는 진료.',lead:'눈꺼풀과 눈 주변의 증상을 확인하고 진료 방향을 상담합니다.',image:'image4.png',definition:'눈꺼풀이나 눈 주변의 불편이 시생활에 영향을 주는지 살펴보는 진료입니다. 증상과 눈의 상태를 확인한 뒤 필요한 검사 및 치료를 상담합니다.',symptoms:['눈꺼풀이 내려와 불편합니다.','눈 주변에 반복적인 불편이 있습니다.','눈물이 흐르는 증상이 지속됩니다.','눈꺼풀 모양이나 기능이 달라졌습니다.'],exams:[['증상 상담','불편이 시작된 시기와 변화, 이전 치료 여부를 확인합니다.'],['눈 주변 상태 확인','눈꺼풀과 눈 표면 등의 상태를 살펴 필요한 진료 방향을 안내합니다.']],treatments:[['진료 후 치료 방향 상담','증상의 원인과 정도에 따라 적합한 관리 및 치료를 상담합니다.'],['설명과 경과 확인','치료 선택지와 주의사항, 경과 관찰에 대해 안내합니다.']]},
 'care-exam':{title:'안종합검진',group:4,en:'EYE EXAMINATION',headline:'잘 보이는 눈도,<br>건강한지 살펴봅니다.',lead:'증상과 연령, 가족력에 맞춰 필요한 눈 검사를 상담합니다.',image:'image11.png',definition:'안종합검진은 시력과 굴절 상태뿐 아니라 수정체, 망막, 시신경 등 눈의 건강을 확인하는 검사입니다. 모든 검사를 일괄 시행하기보다 눈 상태와 필요에 맞춰 선택합니다.',tests:['시력·굴절검사','안압검사','세극등검사','안저검사','시신경 상태 확인','필요한 추가 정밀검사'],exams:[['문진과 기본검사','증상과 병력, 가족력 및 시력·굴절 상태를 확인합니다.'],['눈 건강 확인','눈 상태에 따라 필요한 정밀검사를 선택합니다.']],treatments:[['검사 결과 상담','현재 눈 상태와 필요한 관리 방향을 설명합니다.'],['정기검진 계획','연령, 위험요인과 검사 결과에 따라 검사 간격을 안내합니다.']],faq:[['방문 전에 무엇을 준비하면 좋나요?','사용 중인 안경과 복용약 정보, 이전 검사 자료가 있다면 가져오세요. 검사 준비사항은 방문 전 전화로 확인하실 수 있습니다.']]}
};
const link=r=>r? r+'.html':'index.html';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const img=(file,alt,extra='')=>{const tag='<img src="assets/'+file+'" alt="'+esc(alt)+'" loading="lazy" '+extra+'>';return ['image7.png','image18.png'].includes(file)?'<span class="photo-crop">'+tag+'</span>':tag;};
const head=(en,title,aside='')=>'<div class="section-head"><div><p class="eyebrow">'+en+'</p><h2>'+title+'</h2></div>'+aside+'</div>';
const doctorCards=()=>'<div class="doctor-grid" id="doctor-track" aria-label="3인 의료진 소개"><a class="doctor-card" href="'+link('about-doctors')+'"><div class="doctor-photo original">'+img('director-cutout.png','이정헌 대표원장')+'</div><div class="doctor-meta"><p class="role">안과 전문의</p><h3>이정헌<small>대표원장</small></h3><p class="doctor-statement"><span class="statement-line"><span>눈의 변화에 귀 기울이고,</span></span><span class="statement-line"><span>진료의 방향을 함께 생각합니다.</span></span></p><div class="doctor-bio"><h4>약력</h4><ul><li>인제대학교 부산백병원 안과 전문의</li><li>해군포항병원 안과 주임과장 역임</li><li>밝은세상안과 원장 역임</li><li>국립부산보훈병원 안과 책임과장 역임</li></ul></div></div></a>'+[['02','망막·녹내장'],['03','소아안과']].map(([n,t])=>'<a class="doctor-card" href="'+link('about-doctors')+'"><div class="doctor-photo doctor-placeholder"><span class="profile-number">'+n+'</span><p>분야별 안과 전문의<br>의료진 소개 준비 중</p></div><div class="doctor-meta"><p class="role">3인 전문의 진료 체계</p><h3>'+t+'</h3><p>상세 프로필은 확인 후 안내드립니다.</p></div></a>').join('')+'</div>';
const visit=()=>'<div class="visit-grid"><div><div class="location-photo">'+img('image24.png','주례성모안과 접수 공간')+'<div class="location-pin"><strong>주례역 5번출구 앞</strong><p>엠스퀘어메디컬센터 9층 · 부산 사상구 가야대로 276</p></div></div><div class="location-actions"><a class="button" href="https://map.naver.com/p/search/'+encodeURIComponent('주례성모안과')+'" target="_blank" rel="noopener noreferrer">네이버 지도 보기</a><button class="button" data-copy-address>주소 복사</button></div><p class="note">지하철 2호선 주례역 5번출구 앞<br>주차 이용 방법은 방문 전 전화로 문의해 주세요.</p></div><div class="visit-info"><h3>진료시간</h3><dl class="hours"><div><dt>평일</dt><dd>09:00 — 18:00</dd></div><div><dt>토요일</dt><dd>09:00 — 13:00</dd></div><div><dt>점심시간</dt><dd>13:00 — 14:00</dd></div><div class="closed"><dt>일요일·공휴일</dt><dd>휴진</dd></div></dl><h3>오시는 길</h3><address>부산 사상구 가야대로 276<br>엠스퀘어메디컬센터 9층</address><a class="phone-large" href="tel:0513251919">051.325.1919</a><p class="note">진료와 내원에 관한 궁금한 점을 문의해 주세요.</p></div></div>';

const MAIN_CARE=[['노안·백내장','CATARACT & PRESBYOPIA','뿌옇게 흐려진 시야,<br>원인부터 찾습니다.','시야의 변화를 살피고 생활에 맞는 진료 방향을 함께 상담합니다.','cataract','image7.png'],['망막·녹내장','RETINA & GLAUCOMA','보이지 않는 부분까지,<br>정밀하게 살핍니다.','망막과 시신경의 상태, 시야의 변화를 함께 확인합니다.','retina-amd','image8.png'],['소아안과','PEDIATRIC EYE CARE','아이의 눈은,<br>더 이른 관심이 필요합니다.','사시·약시와 굴절 상태, 아이의 시력 발달을 함께 살펴봅니다.','pediatric-strabismus','image9.png']];
const CARE_SERVICES=[
 ['시력교정','VISION CORRECTION','눈의 굴절 상태와 생활 습관을 확인하고, 나에게 맞는 교정 방법을 상담합니다.','care-exam','vision','clinic-interior.jpg'],
 ['노안','PRESBYOPIA','가까운 글씨가 흐려지는 변화, 눈 상태와 생활 거리에 맞춰 살펴봅니다.','presbyopia','presbyopia','clinic-interior.jpg'],
 ['백내장','CATARACT','뿌옇게 흐려지는 시야의 원인을 확인하고 진료 방향을 함께 상담합니다.','cataract','cataract','clinic-interior.jpg'],
 ['황반변성','MACULAR DEGENERATION','중심 시야의 변화를 듣고 망막 상태를 세심하게 확인합니다.','retina-amd','macular','clinic-interior.jpg'],
 ['소아안과','PEDIATRIC EYE CARE','아이의 굴절 상태와 시력 발달을 살펴봅니다.','pediatric-strabismus','photo','image9.png'],
 ['드림렌즈','DREAM LENS','아이의 눈 상태와 생활 습관에 맞춰 렌즈 상담을 진행합니다.','pediatric-dream','photo','care-dream.jpg'],
 ['안구건조증','DRY EYE CARE','눈의 불편함과 상태를 확인하고 검사·관리 방향을 안내합니다.','care-dry','photo','care-dry.jpg'],
 ['안종합검진','EYE EXAMINATION','시력부터 눈 건강까지, 필요한 검사를 차근차근 안내합니다.','care-exam','photo','care-exam.jpg']
];
function careTabs(){
 const reading='<div class="care-reading-card" aria-hidden="true"><small>YOUR EYES, OUR PROMISE</small><strong>당신의 눈,<br>우리의 약속.</strong><span>가까운 글씨를 천천히 읽어 보세요.</span></div>';
 return '<div class="care-experience"><div class="care-view"><div class="care-view-heading"><span class="eyebrow">A CLEARER VIEW</span><span class="care-view-count" aria-live="polite">01 / 08</span></div><div class="care-comparison" data-mode="vision" style="--split:50%"><p id="care-compare-help" class="care-drag-help">↔ 좌우로 움직여 화면을 비교해 보세요</p><img class="care-scene" src="assets/clinic-interior.jpg" alt="시야 변화 비교를 위한 주례성모안과 공간 사진" loading="lazy" draggable="false">'+reading+'<div class="care-scene-soft" aria-hidden="true"><img src="assets/clinic-interior.jpg" alt="시야 변화 연출 예시" loading="lazy" draggable="false">'+reading+'</div><div class="care-comparison-labels" aria-hidden="true"><span data-care-before>흐릿한 시야 예시</span><span>선명한 화면</span></div><div class="care-divider" aria-hidden="true"><span>‹ <i></i> ›</span></div><input class="care-range" type="range" min="0" max="100" value="50" aria-label="시야 변화 예시와 선명한 화면 비교 위치" aria-valuetext="시야 변화 예시 50%, 선명한 화면 50%" aria-describedby="care-compare-help"></div><div class="care-view-caption"><div><h3 id="care-view-caption">시력교정</h3><p class="care-active-copy">'+CARE_SERVICES[0][2]+'</p></div><a class="care-active-link" href="care-exam.html">진료 자세히 보기 <span aria-hidden="true">↗</span></a></div><p class="care-simulation-note">이해를 돕기 위한 시야 연출입니다. 실제 증상이나 치료 결과를 나타내지 않습니다.</p></div><div class="care-services" role="group" aria-label="주요 진료 분야 선택">'+CARE_SERVICES.map(([title,en,copy,route,mode,file],i)=>'<button type="button" class="care-service" data-care-service="'+i+'" data-title="'+title+'" data-copy="'+esc(copy)+'" data-route="'+link(route)+'" data-mode="'+mode+'" data-image="assets/'+file+'" aria-pressed="'+(i===0)+'"><span class="care-number">'+String(i+1).padStart(2,'0')+'</span><span class="care-service-name">'+title+'</span><span class="care-service-en">'+en+'</span><span class="care-service-arrow" aria-hidden="true">↗</span></button>').join('')+'</div></div>';
}
function equipmentSection(){
 return '<section class="section wrap" id="equipment">'+head('PRECISION & CARE','정밀검사·수술 장비','<div class="equipment-toolbar" data-enhancement hidden><button class="round-button" data-equipment="-1" aria-label="이전 장비">‹</button><button class="round-button" data-equipment="1" aria-label="다음 장비">›</button></div>')+'<div class="content-tabs equipment-tabs" data-tabs="equipment"><nav class="content-tablist" aria-label="검사와 수술 장비" data-enhancement hidden>'+EQUIPMENT.map(([title],i)=>'<button id="equipment-tab-'+i+'" data-tab="'+i+'">'+title+'</button>').join('')+'</nav><div class="equipment-track content-panels" aria-label="검사와 수술 장비" tabindex="0">'+EQUIPMENT.map(([title,copy,file],i)=>'<article class="equipment-card content-panel" id="equipment-panel-'+i+'" data-panel="'+i+'"><div class="equipment-image">'+img(file,title)+'</div><div class="tab-copy"><p class="eyebrow">PRECISION & CARE</p><h3>'+title+'</h3><p>'+copy+'</p><span class="equipment-position">0'+(i+1)+' / 0'+EQUIPMENT.length+'</span></div></article>').join('')+'</div></div></section>';
}
function doctorControls(){return '<div class="doctor-controls" data-enhancement hidden><button class="round-button" data-doctor="-1" aria-label="이전 의료진">‹</button><span id="doctor-position" aria-live="polite" aria-atomic="true">1 / 3</span><button class="round-button" data-doctor="1" aria-label="다음 의료진">›</button></div>';}

function home(){
 return "<section class=\"hero hero-video\" aria-label=\"주례성모안과 소개 영상\"><div class=\"hero-visual\"><video id=\"hero-video\" autoplay muted loop playsinline preload=\"metadata\" poster=\"assets/clinic-hero-poster.jpg\" aria-label=\"병원 공간과 의료진의 진료 모습을 담은 소개 영상\"><source src=\"assets/clinic-hero.mp4\" type=\"video/mp4\"></video></div><div class=\"hero-copy\"><p class=\"eyebrow\">YOUR EYES, OUR PROMISE</p><h1 id=\"hero-title\">당신의 눈,<br>우리의 약속.</h1><p class=\"hero-intro\">각자의 전문 분야를 가진<br><strong>3인의 안과 전문의</strong>가 함께합니다.</p><a class=\"button\" href=\"about-doctors.html\">의료진 소개 <span aria-hidden=\"true\">↗</span></a><p class=\"hero-footnote\">노안·백내장 · 망막·녹내장 · 소아안과</p></div><div class=\"hero-video-toolbar\"><span>JURYE ST. MARY’S EYE CLINIC</span><button type=\"button\" data-video-play aria-label=\"소개 영상 일시정지\" aria-pressed=\"false\" hidden><span data-video-icon aria-hidden=\"true\">Ⅱ</span><span data-video-label>일시정지</span></button></div></section>"+
 '<div class="wrap intro-strip"><p class="serif">Since 2013. With you, always.</p><p>사상구 주례동에서, 당신의 눈 건강을 함께 살핍니다.</p></div>'+
 '<section class="section wrap" id="doctors">'+head('OUR DOCTORS','서로 다른 전문 분야,<br>함께하는 세심한 진료.','<a class="text-link" href="'+link('about-doctors')+'">의료진 소개</a>')+doctorCards()+doctorControls()+'</section>'+
 '<section class="section care-showcase" id="care"><div class="wrap">'+head('SPECIALIZED CARE','주례성모안과 주요 진료','')+careTabs()+'</div></section>'+
 '<section class="history-section wrap" id="history" aria-label="2013년부터 이어온 진료"><div class="capsule-stage">'+['image13.png','image14.png','image15.png','image16.png','image17.png'].map(f=>img(f,'주례성모안과의 진료와 공간')).join('')+'<div class="history-copy"><small>SINCE</small><span class="year">2013</span><p>사상구 주례동에서 <span class="history-count" data-count="13" aria-hidden="true">13</span><span aria-hidden="true">년</span><span class="sr-only">13년</span><br>안과 전문의 3인 진료</p></div></div></section>'+
 '<section class="mission" id="promise"><div class="wrap mission-layout"><div class="mission-copy"><p class="eyebrow">OUR PROMISE</p><h2>세상을 더 선명하게<br>볼 수 있도록.</h2><p>눈 건강을 세심하게 살피고, 시력 회복과 지속적인 눈 건강 관리를 돕는 것. 주례성모안과가 지켜가는 진료의 방향입니다.</p><div class="promise-grid">'+PROMISES.map(([t],i)=>'<div><span>0'+(i+1)+'</span><h3>'+t+'</h3></div>').join('')+'</div><a class="text-link" href="'+link('about-philosophy')+'">우리가 지키는 약속</a></div><div class="mission-photo">'+img('image18.png','수술 현미경을 통해 눈을 살피는 의료진')+'</div></div></section>'+
 equipmentSection()+
 '<section class="section white" id="space"><div class="wrap">'+head('OUR SPACE','머무는 순간까지,<br>편안하도록.','<a class="text-link" href="'+link('about-facilities')+'">병원 공간 둘러보기</a>')+'<div class="space-grid">'+SPACES.map(([t,f])=>'<a href="'+link('about-facilities')+'">'+img(f,t)+'<span>'+t+'</span></a>').join('')+'</div></div></section>'+
 '<section class="section wrap" id="visit">'+head('VISIT US','가까이에서 함께하는<br>당신의 눈 건강.')+visit()+'</section>';
}
function pageHero(title,group,en,headline,lead,image){
 return '<section class="page-hero wrap"><div class="breadcrumb"><a href="index.html">홈</a><span>/</span><span>'+esc(group)+'</span><span>/</span><span>'+esc(title)+'</span></div><div class="page-hero-layout"><div><p class="eyebrow">'+en+'</p><h1>'+headline+'</h1><p class="lead">'+lead+'</p></div>'+img(image,title+' 관련 사진')+'</div></section>';
}
function section(en,title,body){return '<section class="content-section"><div class="content-layout"><div><p class="eyebrow">'+en+'</p><h2>'+title+'</h2></div><div>'+body+'</div></div></section>'}
function list(items){return '<ol class="numbered-list">'+items.map(([t,p],i)=>'<li><span class="num">0'+(i+1)+'</span><div><h3>'+t+'</h3><p>'+p+'</p></div></li>').join('')+'</ol>'}
function tabs(group,current){return '<nav class="page-tabs" aria-label="'+esc(MENU[group][0])+' 세부 메뉴">'+MENU[group][1].map(([t,r])=>'<a href="'+link(r)+'" '+(r===current?'aria-current="page"':'')+'>'+t+'</a>').join('')+'</nav>'}
function carePage(key){
 const p=PAGES[key];
 let body=pageHero(p.title,MENU[p.group][0],p.en,p.headline,p.lead,p.image)+'<div class="wrap">'+tabs(p.group,key);
 body+=section('UNDERSTANDING',p.title+' 안내','<p>'+p.definition+'</p>');
 if(p.symptoms)body+=section('WHAT TO NOTICE',p.symptomTitle||'이런 변화를<br>살펴보세요','<div class="symptom-grid">'+p.symptoms.map(t=>'<div class="symptom-item"><span aria-hidden="true">✓</span><p>'+t+'</p></div>').join('')+'</div>'+(p.symptomTitle?'':'<p class="note">증상만으로 질환을 판단하기는 어렵습니다. 검사와 진료를 통해 원인을 확인하세요.</p>'));
 if(p.tests)body+=section('EXAMINATION','검진 항목','<div class="test-grid">'+p.tests.map(t=>'<div>'+t+'</div>').join('')+'</div><p class="note">모든 항목을 일괄 시행하지 않으며, 눈 상태와 연령에 따라 필요한 검사를 선택합니다.</p>');
 body+=section('DIAGNOSIS','검사',list(p.exams))+section('CARE & TREATMENT','관리·치료 방향',list(p.treatments));
 if(p.faq)body+=section('QUESTIONS','자주 묻는 질문','<div class="faq">'+p.faq.map(([q,a])=>'<details><summary>'+q+'</summary><p>'+a+'</p></details>').join('')+'</div>');
 body+='<p class="notice">'+(p.notice||'검사와 치료 방법은 눈 상태에 따라 달라집니다. 진료 후 의료진과 함께 결정합니다.')+'</p>';
 body+='<p class="source-note">진료 안내: 홈페이지 리뉴얼 기획안'+(p.source?' · 일반 질환 정보 참고: <a href="'+NEI+p.source+'" target="_blank" rel="noopener noreferrer">National Eye Institute</a>':'')+'</p></div>';
 return body;
}
function aboutPage(key){
 const titles={'about-greeting':['인사말','당신의 눈,<br>우리의 약속.','눈 건강을 함께 살피는 주례성모안과입니다.','image3.png'],'about-doctors':['의료진 소개','서로 다른 전문 분야,<br>함께하는 세심한 진료.','3인의 분야별 안과 전문의가 함께합니다.','image3.png'],'about-philosophy':['진료 철학','세상을 더 선명하게<br>볼 수 있도록.','우리가 매일 지켜가는 여섯 가지 진료 기준.','image18.png'],'about-history':['연혁','2013년부터,<br>주례동에서 함께.','지역의 눈 건강을 함께 살펴온 시간입니다.','image1.png'],'about-facilities':['시설','머무는 순간까지,<br>편안하도록.','진료와 검사, 대기의 모든 시간을 생각하는 공간.','image23.png'],'about-location':['오시는길','가까이에서 함께하는<br>당신의 눈 건강.','지하철 2호선 주례역 5번출구 앞, 엠스퀘어메디컬센터 9층.','image24.png']};
 const [title,headline,lead,image]=titles[key];
 let body=pageHero(title,'병원소개','JURYE ST. MARY’S EYE CLINIC',headline,lead,image)+'<div class="wrap">'+tabs(0,key);
 if(key==='about-greeting')body+='<article class="greeting"><p class="eyebrow">YOUR EYES, OUR PROMISE</p><h2>눈의 변화에 귀 기울이고,<br>진료의 방향을 함께 생각합니다.</h2><p>주례성모안과는 2013년 개원 이후 사상구 주례동에서 진료를 이어오고 있습니다. 노안·백내장, 망막·녹내장, 소아안과 등 서로 다른 분야를 가진 3인의 안과 전문의가 함께합니다.</p><p>잘 보이는 일상은 작은 눈의 변화에 관심을 갖는 것에서 시작됩니다. 환자분의 불편을 충분히 듣고 눈 상태를 세심하게 살피며, 검사 결과와 치료 방향을 이해하기 쉽게 설명하고자 합니다.</p><p>눈 건강을 세심하게 살피고, 시력 회복과 지속적인 눈 건강 관리를 돕는 것. 이것이 주례성모안과가 지켜가는 약속입니다.</p><p class="signature">주례성모안과 의료진</p></article>';
 if(key==='about-doctors')body+='<article class="profile-detail"><div class="doctor-photo original">'+img('director-clinic-logo.png','이정헌 대표원장')+'</div><div><p class="role">안과 전문의</p><h2 class="doctor-detail-name">이정헌 <small>대표원장</small></h2><div class="doctor-bio biography-columns"><div><h4>약력</h4><ul><li>인제대학교 부산백병원 안과 전문의</li><li>해군포항병원 안과 주임과장 역임</li><li>밝은세상안과 원장 역임</li><li>국립부산보훈병원 안과 책임과장 역임</li></ul></div><div><h4>연수 및 학회 활동</h4><ul><li>일본국립 오사카대학부속병원 안과 연수(백내장)</li><li>일본국립 시가대학부속병원 안과 연수(백내장)</li><li>일본 오사카로사이병원 안과 연수(백내장)</li><li>대한안과학회 정회원</li><li>한국백내장굴절수술 연구회 정회원</li><li>한국사시소아안과학회 정회원</li><li>한국외안부 연구회 정회원</li><li>한국콘택트렌즈학회 정회원</li><li>미국백내장굴절수술학회 정회원</li><li>아시아태평양굴절수술학회 정회원</li><li>일본안과수술학회 정회원</li></ul></div></div></div></article>'+['망막·녹내장','소아안과'].map(t=>'<article class="profile-pending"><p class="eyebrow">SPECIALIST</p><h3>'+t+'</h3><p>분야별 안과 전문의의 상세 프로필은 확인 후 안내드립니다.</p></article>').join('')+'<p class="source-note">의료진의 성함·사진·세부 약력은 확인된 자료에 맞춰 업데이트할 예정입니다.</p>';
 if(key==='about-philosophy')body+='<section class="content-section"><div class="greeting"><p>눈 건강을 세심하게 살피고, 시력 회복과 지속적인 눈 건강 관리를 돕는 것. 주례성모안과가 지켜가는 진료의 방향입니다.</p></div><div class="promise-detail">'+PROMISES.map(([t,p],i)=>'<article><span>0'+(i+1)+'</span><h3>'+t+'</h3><p>'+p+'</p></article>').join('')+'</div></section>';
 if(key==='about-history')body+='<section class="content-section"><div class="history-list"><span>2013</span><div><h3>주례성모안과 개원</h3><p>사상구 주례동에서 눈 건강을 위한 진료를 시작했습니다.</p></div></div><div class="history-list"><span>2026</span><div><h3>3인의 분야별 안과 전문의</h3><p>노안·백내장, 망막·녹내장, 소아안과를 중심으로 함께 진료합니다.</p></div></div></section>';
 if(key==='about-facilities')body+='<section class="content-section"><div class="facility-gallery">'+SPACES.map(([t,f,p])=>'<article><button class="image-button" data-photo="'+f+'" data-photo-title="'+t+'" aria-label="'+t+' 사진 크게 보기">'+img(f,t)+'<h3>'+t+'</h3></button><p>'+p+'</p></article>').join('')+'</div></section>';
 if(key==='about-location')body+='<section class="content-section">'+visit()+'</section>';
 return body+'</div>';
}
const ROUTES=['',...MENU.flatMap(([,items])=>items.map(([,r])=>r))];
function renderPage(key){return key===''?home():PAGES[key]?carePage(key):key.startsWith('about-')?aboutPage(key):'<section class="section wrap"><h1>페이지를 찾을 수 없습니다.</h1><a class="button" href="index.html">홈으로</a></section>';}
function titleFor(key){return PAGES[key]?.title||MENU.flatMap(([,items])=>items).find(([,r])=>r===key)?.[0]||'당신의 눈, 우리의 약속';}
if(typeof module!=='undefined')module.exports={CONFIG,MENU,ROUTES,renderPage,titleFor,link};
if(typeof document!=='undefined'){
 const menu=document.getElementById('mega'),toggle=document.getElementById('menu-toggle'),nav=document.getElementById('nav');
 const file=location.pathname.split('/').pop(),route=file==='index.html'||!file?'':file.replace(/\.html$/,'');
 nav.innerHTML=MENU.map(([t,items])=>'<a href="'+link(items[0][1])+'">'+t+'</a>').join('');
 menu.innerHTML=MENU.map(([t,items])=>'<div><h2>'+t+'</h2>'+items.map(([s,r])=>'<a href="'+link(r)+'">'+s+'</a>').join('')+'</div>').join('');
 function showMenu(open){menu.hidden=!open;toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'전체 메뉴 닫기':'전체 메뉴 열기');}
 toggle.addEventListener('click',()=>showMenu(menu.hidden));
 nav.addEventListener('mouseenter',()=>{if(matchMedia('(hover:hover) and (min-width:901px)').matches)showMenu(true);});
 document.querySelector('.header').addEventListener('mouseleave',()=>{if(matchMedia('(hover:hover) and (min-width:901px)').matches)showMenu(false);});
 document.addEventListener('click',e=>{if(!e.target.closest('.header'))showMenu(false);});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!menu.hidden&&!document.getElementById('dialog')?.open){showMenu(false);toggle.focus();}});
 const dialog=document.getElementById('dialog'),content=document.getElementById('dialog-content');
 function showDialog(title,html){content.innerHTML='<h2 id="dialog-title">'+esc(title)+'</h2>'+html;dialog.showModal();}
 dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());
 dialog.addEventListener('click',e=>{if(e.target===dialog){const b=dialog.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)dialog.close();}});
 document.addEventListener('click',async e=>{
  const b=e.target.closest('button');if(!b)return;
  if(b.dataset.channel){const key=b.dataset.channel,url=CONFIG.channels[key];if(url){const parsed=new URL(url);if(parsed.protocol==='https:')window.open(parsed.href,'_blank','noopener,noreferrer');}else showDialog({kakao:'카카오톡 상담',naver:'네이버 예약',consult:'온라인 상담'}[key],'<p>현재 온라인 연결을 준비 중입니다.<br>진료와 내원 문의는 전화로 안내해 드립니다.</p><a class="button solid" href="tel:0513251919">051-325-1919 전화 문의</a>');}
  if(b.dataset.modal==='fees')showDialog('비급여 안내',CONFIG.fees.length?'<div class="fee-list">'+CONFIG.fees.map(f=>'<p>'+esc(f.name)+' · '+esc(f.price)+'</p>').join('')+'</div>':'<p>비급여 항목과 비용은 병원 확인 후 안내됩니다.</p><p>진료와 검사에 따른 비용은 전화로 문의해 주세요.</p><a class="button" href="tel:0513251919">비용 문의</a>');
  if(b.dataset.modal==='privacy')showDialog('개인정보처리방침','<p>메인 화면의 챗봇은 입력한 질문을 병원 안내 답변에 사용합니다. 이 홈페이지는 대화를 저장하지 않습니다. 이름·연락처·진료 기록 등 개인정보를 입력하지 마세요. 생성형 답변 기능이 설정된 경우 질문과 관련 안내 자료가 OpenAI API로 전달될 수 있습니다.</p><h3>외부 서비스 이용</h3><p>지도·상담·예약 서비스로 이동하는 경우 해당 서비스의 개인정보처리방침을 확인해 주세요.</p><h3>문의</h3><p>개인정보 관련 문의: 주례성모안과의원<br>051-325-1919 · maryeye1919@naver.com</p><p class="note">병원 운영 정책이 확정되면 상세 방침을 안내합니다.</p>');
  if(b.hasAttribute('data-copy-address')){try{await navigator.clipboard.writeText('부산 사상구 가야대로 276 엠스퀘어메디컬센터 9층');b.textContent='주소를 복사했습니다';setTimeout(()=>b.textContent='주소 복사',2200);}catch{showDialog('주소','<p>부산 사상구 가야대로 276<br>엠스퀘어메디컬센터 9층</p><p>주소를 선택하여 복사해 주세요.</p>');}}
  if(b.dataset.photo)showDialog(b.dataset.photoTitle,'<img class="dialog-image" src="assets/'+esc(b.dataset.photo)+'" alt="'+esc(b.dataset.photoTitle)+'">');
 });
 document.querySelector('.back-top').addEventListener('click',()=>window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'}));
}
